#include "settings_menu.hpp"
#include <algorithm>
namespace arcade {
const char* category_name(SettingsCategory c){static const char* names[]={"Profiles","Video","Performance","Audio","Controls","Accessibility","Diagnostics","Game files","Appearance","Colour"};return names[std::clamp(int(c),0,settings_category_count-1)];}
const char* category_note(SettingsCategory c){static const char* notes[]={"Separate favorites and game saves.","Picture, filters and FPS overlay.","Game speed and focus behavior.","Game volume, mute and menu sounds.","Buttons, shortcuts and vibration.","Text size, contrast and motion.","Logging and engine information.","ROM folders, scans and save backups.","Day, Night and your own wallpaper.","Choose the Gallery accent colour."};return notes[std::clamp(int(c),0,settings_category_count-1)];}
std::vector<SettingRow> category_rows(SettingsCategory c){using I=SettingId;
 switch(c){
 case SettingsCategory::Profiles:return {{I::Profile,"Playing as","Each player keeps separate favorites and MAME saves."},{I::SaveLocation,"Save folder","Player 1 keeps the original save location."}};
 case SettingsCategory::Video:return {{I::Renderer,"Game renderer","OpenGL is the default. Advanced Vulkan presents directly to the PS5 display."},{I::Output,"Output resolution","PS5 display size. Applies after restarting Arcade."},{I::Refresh,"Refresh rate","Applies after restarting. Unsupported TVs remain at 60 Hz."},{I::Scaling,"Picture size","Original proportions, integer scaling or full screen."},{I::Filter,"Upscaling filter","Sharp pixels or smooth interpolation."},{I::Rotation,"Rotation","Game orientation is automatic. Apply an extra turn for your display."},{I::PostProcessing,"Post-processing","Scanlines and a simple CRT display effect."},{I::Overlay,"FPS overlay","Show actual frame rate and game performance."},{I::OverlayOptions,"Overlay options","Choose the overlay fields, size, corner and colours."}};
 case SettingsCategory::Performance:return {{I::Speed,"Speed limit","Changes emulation speed. Faster games may change audio pitch."},{I::PauseOnFocus,"Pause when interrupted","Pause the game when the system takes controller focus."}};
 case SettingsCategory::Audio:return {{I::Volume,"Game volume","Adjust stereo game audio."},{I::Mute,"Mute","Silence game and menu audio."},{I::MenuVolume,"Menu volume","Volume of background music and menu sounds."},{I::MenuMusic,"Background music","Play the arcade soundtrack in the main hall."}};
 case SettingsCategory::Controls:return {{I::CoinButton,"Insert coin","Choose the shortcut that adds arcade credits."},{I::StartButton,"Start game","Choose the shortcut that presses Player Start."},{I::Mapping,"Button mapping","Assign the four face buttons to MAME action buttons."},{I::MenuKeys,"Menu keybinds","Choose confirm and back. Gameplay buttons stay separate."},{I::Vibration,"Vibration","Controller feedback when confirming menu choices."},{I::VibrationStrength,"Vibration strength","Preview the strength on the controller."}};
 case SettingsCategory::Accessibility:return {{I::LargeText,"Larger text","Enlarge small menu text while keeping labels inside their rows."},{I::HighContrast,"High contrast","Solid panels, brighter text and an outlined selection."},{I::ReduceMotion,"Reduce motion","Use a still background and stop sliding menu animations."}};
 case SettingsCategory::Diagnostics:return {{I::DetailedLogs,"Detailed logging","Include MAME debug messages. Applies to the next game launch."},{I::ImmediateLogs,"Write logs at once","Flush diagnostics to disk immediately; this may cause stutter."},{I::LogLocation,"Log location","PS5: /data/arcade-startup.log"},{I::Backend,"Arcade engine","MAME version and selected graphics renderer."}};
 case SettingsCategory::Files:return {{I::GameFolder,"Game folder","Browse folders with the D-pad. Triangle chooses a folder."},{I::Rescan,"Refresh library","Find arcade archives added to the selected folder."},{I::SaveLocation,"Save folder","MAME configuration, NVRAM and saves for the active player."},{I::BackupSaves,"Back up saves","Create a new local backup without replacing existing backups."}};
 case SettingsCategory::Appearance:return {{I::Theme,"Theme","Your approved Gallery design in Day or Night."},{I::Wallpaper,"Wallpaper","Choose a PNG from the app data wallpapers folder."}};
 case SettingsCategory::Colour:return {{I::Accent,"Accent colour","Changes selected cards, menu highlights and primary buttons."}};
 default:return {};
 }
}
std::vector<SettingRow> overlay_rows(){using I=SettingId;return {{I::HudColors,"Enable colours","Use the current accent colour in the overlay."},{I::HudSize,"Size","Choose Regular, Medium or Large."},{I::HudCorner,"Corner","Keep the overlay away from game information."},{I::HudBackend,"Backend","Show the MAME / OpenGL backend name."},{I::HudFps,"FPS","Actual presented gameplay frames per second."},{I::HudMs,"Frame time","Time spent emulating and drawing each frame."},{I::HudSpeed,"Speed","Actual game speed compared with its native frame rate."},{I::HudResolution,"Resolution","The game's original frame dimensions."}};}
std::vector<SettingRow> mapping_rows(){using I=SettingId;return {{I::ActionCross,"Cross","MAME action assigned to Cross."},{I::ActionCircle,"Circle","MAME action assigned to Circle."},{I::ActionSquare,"Square","MAME action assigned to Square."},{I::ActionTriangle,"Triangle","MAME action assigned to Triangle."},{I::ResetMapping,"Reset mapping","Restore the standard four face-button assignments."}};}
namespace {std::string on(bool v){return v?"On":"Off";}template<size_t N>std::string pick(const char* const(&v)[N],int i){return v[std::clamp(i,0,int(N)-1)];}}
std::string setting_value(SettingId id,const Settings& s){using I=SettingId;
 static const char* output[]={"1080p","1440p","2160p"},*scaling[]={"Original proportions","Integer scaling","Full screen"},*rotation[]={"Automatic","Auto + 90 degrees","Auto + 180 degrees","Auto + 270 degrees"},*effects[]={"Off","Scanlines","CRT","Bloom (Vulkan)","Phosphor (Vulkan)","LCD (Vulkan)"},*speed[]={"50%","75%","100%","125%","150%","200%","300%","400%"},*coins[]={"L3 or Create","L3","Create","L1"},*starts[]={"Options or R3","Options","R3"},*accents[]={"Gallery orange","Amber","Coral","Mint","Cyan","Blue","Violet","Rose"},*sizes[]={"Regular","Medium","Large"},*corners[]={"Top left","Top right","Bottom left","Bottom right"},*actions[]={"Action 1 (B)","Action 2 (A)","Action 3 (Y)","Action 4 (X)","Action 5 (L1)","Action 6 (R1)","Action 7 (L2)","Action 8 (R2)"};
 switch(id){
 case I::Renderer:return s.renderer?"Vulkan (advanced)":"OpenGL (default)";case I::Profile:return "Player "+std::to_string(s.profile+1);case I::Output:return pick(output,s.output);case I::Refresh:return s.refresh?"120 Hz requested":"60 Hz";case I::Scaling:return pick(scaling,s.scaling);case I::Filter:return s.smooth?"Smooth":"Sharp pixels";case I::Rotation:return pick(rotation,s.rotation);case I::PostProcessing:return pick(effects,s.post_processing);case I::Overlay:return on(s.overlay);case I::Speed:return pick(speed,s.speed);case I::PauseOnFocus:return on(s.pause_on_focus);case I::Volume:return std::to_string(s.volume)+"%";case I::Mute:return on(s.mute);case I::MenuMusic:return on(s.menu_music);case I::MenuVolume:return s.menu_volume?std::to_string(s.menu_volume)+"%":"Off";case I::Vibration:return on(s.vibration);case I::VibrationStrength:return std::to_string(s.vibration_strength)+"%";case I::MenuKeys:return s.swap_menu?"Circle confirms / Cross goes back":"Cross confirms / Circle goes back";case I::CoinButton:return pick(coins,s.coin_button);case I::StartButton:return pick(starts,s.start_button);case I::LargeText:return on(s.large_text);case I::HighContrast:return on(s.high_contrast);case I::ReduceMotion:return on(s.reduce_motion);case I::DetailedLogs:return on(s.detailed_logging);case I::ImmediateLogs:return on(s.immediate_logs);case I::LogLocation:return "View location";case I::Backend:return s.renderer?"MAME 0.289 / Vulkan":"MAME 0.289 / OpenGL";case I::Rescan:return "Scan now";case I::BackupSaves:return "Create backup";case I::Theme:return s.theme==Theme::Day?"Day":"Night";case I::Wallpaper:return s.wallpaper.empty()?"None":s.wallpaper;case I::Accent:return pick(accents,s.accent);case I::HudColors:return on(s.hud_colors);case I::HudSize:return pick(sizes,s.hud_size);case I::HudCorner:return pick(corners,s.hud_corner);case I::HudBackend:return on(s.hud_backend);case I::HudFps:return on(s.hud_fps);case I::HudMs:return on(s.hud_ms);case I::HudSpeed:return on(s.hud_speed);case I::HudResolution:return on(s.hud_resolution);case I::ResetMapping:return "Restore defaults";
 case I::ActionCross:case I::ActionCircle:case I::ActionSquare:case I::ActionTriangle:return pick(actions,s.action_buttons[int(id)-int(I::ActionCross)]);
 case I::GameFolder:return s.roms.empty()?"Choose folder":s.roms.string();default:return "Open";
 }
}
bool adjust_setting(SettingId id,Settings& s,int direction){using I=SettingId;int d=direction<0?-1:1;auto cycle=[d](int& v,int n){v=(v+d+n)%n;};
 switch(id){
 case I::Renderer:s.renderer=1-s.renderer;if(!s.renderer)s.post_processing=std::min(s.post_processing,2);break;case I::Profile:cycle(s.profile,4);break;case I::Output:cycle(s.output,3);break;case I::Refresh:s.refresh=1-s.refresh;break;case I::Scaling:cycle(s.scaling,3);break;case I::Filter:s.smooth=!s.smooth;break;case I::Rotation:cycle(s.rotation,4);break;case I::PostProcessing:cycle(s.post_processing,s.renderer?6:3);break;case I::Overlay:s.overlay=!s.overlay;break;case I::Speed:cycle(s.speed,8);break;case I::PauseOnFocus:s.pause_on_focus=!s.pause_on_focus;break;
 case I::Volume:s.volume=std::clamp(s.volume+d*10,0,100);break;case I::Mute:s.mute=!s.mute;break;case I::MenuMusic:s.menu_music=!s.menu_music;break;case I::MenuVolume:s.menu_volume=std::clamp(s.menu_volume+d*10,0,100);break;case I::Vibration:s.vibration=!s.vibration;break;case I::VibrationStrength:s.vibration_strength=std::clamp(s.vibration_strength+d*25,25,100);break;case I::MenuKeys:s.swap_menu=!s.swap_menu;break;case I::CoinButton:cycle(s.coin_button,4);break;case I::StartButton:cycle(s.start_button,3);break;case I::LargeText:s.large_text=!s.large_text;break;case I::HighContrast:s.high_contrast=!s.high_contrast;break;case I::ReduceMotion:s.reduce_motion=!s.reduce_motion;break;case I::DetailedLogs:s.detailed_logging=!s.detailed_logging;break;case I::ImmediateLogs:s.immediate_logs=!s.immediate_logs;break;case I::Theme:s.theme=s.theme==Theme::Day?Theme::Night:Theme::Day;break;case I::Accent:cycle(s.accent,8);break;case I::HudColors:s.hud_colors=!s.hud_colors;break;case I::HudSize:cycle(s.hud_size,3);break;case I::HudCorner:cycle(s.hud_corner,4);break;case I::HudBackend:s.hud_backend=!s.hud_backend;break;case I::HudFps:s.hud_fps=!s.hud_fps;break;case I::HudMs:s.hud_ms=!s.hud_ms;break;case I::HudSpeed:s.hud_speed=!s.hud_speed;break;case I::HudResolution:s.hud_resolution=!s.hud_resolution;break;
 case I::ActionCross:case I::ActionCircle:case I::ActionSquare:case I::ActionTriangle:cycle(s.action_buttons[int(id)-int(I::ActionCross)],8);break;case I::ResetMapping:s.action_buttons={{0,1,2,3}};break;default:return false;
 }return true;
}
}
